<?php if(!defined('ABSPATH'))exit;$items=varastudy_vault_breadcrumb_items();if(!$items)return; ?><nav class="cv-breadcrumbs" aria-label="Breadcrumb"><?php foreach($items as $i=>$item): ?><?php if($i)echo '<span aria-hidden="true">/</span>'; ?><?php if(!empty($item['url'])&&$i<count($items)-1): ?><a href="<?php echo esc_url($item['url']); ?>"><?php echo esc_html($item['label']); ?></a><?php else: ?><span aria-current="page"><?php echo esc_html($item['label']); ?></span><?php endif; ?><?php endforeach; ?></nav>
